<script setup lang="ts">
import {computed,ref,watch} from 'vue';import Panel from '../components/Panel.vue';import SealViewer from '../components/SealViewer.vue'
import {current,api,run,refresh,busy,notify,kindName,isProcessImage} from '../store'
const width=ref(30);const base=ref(8);const relief=ref(1.2);const resolution=ref(96);const style=ref('zhu');const mirror=ref(true);const source=ref('');const color=ref('#ac3b24');const rendered=ref(false)
const model=computed(()=>current.value?.artifacts.filter(a=>a.kind==='stl').at(-1));const images=computed(()=>current.value?.artifacts.filter(isProcessImage)||[])
watch(()=>model.value?.id,()=>{const m=model.value?.metadata;if(!m)return;width.value=m.width_mm;base.value=m.base_mm;relief.value=m.relief_mm;resolution.value=m.resolution;style.value=m.style;mirror.value=m.mirror;source.value=images.value.find(a=>a.id===m.source_artifact_id)?.kind==='original'?'':m.source_artifact_id;rendered.value=false},{immediate:true})
async function build(){await run(async()=>{if(!current.value)throw new Error('请先上传印谱');await api(`/seals/${current.value.id}/reconstruct`,{method:'POST',body:JSON.stringify({width_mm:width.value,base_mm:base.value,relief_mm:relief.value,resolution:resolution.value,style:style.value,mirror:mirror.value,source_artifact_id:source.value||null})});await refresh();rendered.value=false;notify('STL生成完成，网格闭合与法线检查已通过。')})}
const materials=[['寿山石','#ac3b24'],['青田石','#81917f'],['金属','#c6a267'],['树脂','#ded1b4']]
</script>
<template><div class="reconstruction-grid"><Panel title="三维印章建模工作区" note="印面参数建模 · 制造网格自动校验"><SealViewer :key="current?.id" :url="model?.url" :color="color" @loaded="rendered=true"/><div v-if="model" class="model-checks"><span class="pill green">{{model.metadata.watertight?'封闭网格已通过':'待检查'}}</span><span>{{model.metadata.faces.toLocaleString()}} 个三角面</span><span>{{rendered?'浏览器模型已加载':'读取中'}}</span></div></Panel><Panel title="重建参数与导出" note="基于真实印文轮廓生成参数化模型"><div class="tabs"><button :class="{primary:style==='zhu'}" @click="style='zhu'">朱文浮雕</button><button :class="{primary:style==='bai'}" @click="style='bai'">白文凹刻</button></div><label class="param-row">印面宽度<input type="number" min="10" max="100" step="1" v-model.number="width" aria-label="印面宽度"><span>mm</span></label><label class="param-row">印面长度<b>{{width.toFixed(1)}} mm</b></label><label class="param-row">印身高度<input type="number" min="2" max="30" step="1" v-model.number="base" aria-label="印身高度"><span>mm</span></label><label class="param-row">浮雕高度<input type="number" min="0.2" max="5" step="0.1" v-model.number="relief" aria-label="浮雕高度"><span>mm</span></label><label class="param-row">采样精度<select v-model.number="resolution" aria-label="采样精度"><option :value="48">48 × 48</option><option :value="96">96 × 96</option><option :value="128">128 × 128</option></select></label><label class="param-row">实体盖印镜像<input type="checkbox" v-model="mirror" aria-label="实体盖印镜像"></label><label class="version-select">图像来源<select v-model="source" aria-label="重建来源图像"><option value="">原始扫描</option><option v-for="a in images.filter(a=>a.kind!=='original')" :value="a.id" :key="a.id">{{kindName[a.kind]}} · {{a.id.slice(0,8)}}</option></select></label><h3 class="material-title">材质实时预览</h3><div class="materials"><button v-for="[name,c] in materials" :key="name" @click="color=c" :class="{selected:color===c}"><span :style="{backgroundColor:c}"></span>{{name}}</button></div><button class="primary full generate" :disabled="!current||busy" @click="build">生成三维印面</button><a v-if="model" class="button full" :href="model.url" download>↓ 导出 STL 模型</a><p class="hint">此处真实生成印面浮雕，不生成狮钮雕塑。STL按毫米切片；最小笔画、材料和实际盖印效果仍需实物验证。</p><dl v-if="model" class="data-list compact"><div><dt>生成版本</dt><dd>{{model.id.slice(0,8)}}</dd></div><div><dt>体积</dt><dd>{{model.metadata.volume_mm3}} mm³</dd></div><div><dt>镜像参数</dt><dd>{{model.metadata.mirror?'已启用':'未启用'}}</dd></div></dl></Panel></div></template>
